# Ciência Política — lote L14, terceira leva (parte 2: Q06–Q08)
TG="d"
Q = []
TAILS=[" Essa seria a posição predominante na literatura especializada de ciência política.",
 " Trata-se de entendimento consolidado na teoria política contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características do arranjo institucional descrito.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.93*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"doutrina de ciência política; CF","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência e legislação eleitoral","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"CF; leis eleitorais","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def X(q,atom,padE,dif,C,E,com,terro,jur=False,lei=False):
    _n[q]=_n.get(q,0)+1
    P(f"Q{q:02d}",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"{TG}{q:02d}{_n[q]}",jur=jur,lei=lei)
# ---------- Q06 partidos (átomo 43)
X(6,43,"confusao_instituto",3,"Para Duverger, os partidos de quadros reúnem poucos membros, notáveis, e atuam sobretudo em períodos eleitorais, ao passo que os partidos de massas dependem de grande número de filiados e de financiamento por contribuições.","Para Duverger, os partidos de massas reúnem poucos notáveis e atuam apenas em períodos eleitorais, ao passo que os partidos de quadros dependem de grande número de filiados.","Duverger.","inverte quadros e massas")
X(6,43,"confusao_instituto",4,"Para Kirchheimer, o partido catch-all abandona o apelo a uma classe ou confissão específica, desideologiza o discurso e busca votos de todos os segmentos do eleitorado.","Para Kirchheimer, o partido catch-all reforça a identidade ideológica de classe, limita o recrutamento a um segmento do eleitorado e rejeita alianças com outros grupos.","Kirchheimer.","inverte característica")
X(6,43,"confusao_instituto",4,"Katz e Mair propõem o modelo de partido-cartel, no qual os partidos se tornam dependentes de recursos estatais e colaboram entre si para limitar a competição.","Katz e Mair propõem o modelo de partido-cartel, no qual os partidos se mantêm exclusivamente com contribuições de filiados e competem de modo radical entre si, sem recursos estatais.","Katz e Mair.","inverte dependência do Estado")
X(6,43,"confusao_instituto",4,"Para Panebianco, o partido profissional-eleitoral caracteriza-se pelo peso dos profissionais especializados, pela centralidade da campanha eleitoral e por vínculos organizativos mais fracos com os filiados.","Para Panebianco, o partido profissional-eleitoral caracteriza-se pelo predomínio dos burocratas de carreira partidária e pela centralidade da militância de base em detrimento das campanhas.","Panebianco.","inverte características")
X(6,43,"excecao_omitida",3,"Segundo a Constituição, é assegurada aos partidos políticos autonomia para definir sua estrutura interna, organização e funcionamento, e eles adquirem personalidade jurídica na forma da lei civil, registrando seus estatutos no Tribunal Superior Eleitoral.","Segundo a Constituição, os partidos políticos adquirem personalidade jurídica de direito público e registram seus estatutos no Tribunal Regional Eleitoral, sem autonomia para definir a estrutura interna.","CF, art. 17, caput e §§ 1º e 2º.","altera natureza jurídica e autonomia",lei=True)
X(6,43,"troca_numero",3,"A fidelidade partidária, após a decisão do STF de 2007 (MS 26.602 e outros) e a Resolução TSE 22.610, aplica-se aos cargos proporcionais, e a perda do mandato por desfiliação sem justa causa pode ser decretada pela Justiça Eleitoral.","A fidelidade partidária, após a decisão do STF de 2007, aplica-se também aos cargos majoritários, como Senador e Chefe do Executivo, e a perda do mandato dispensa a atuação da Justiça Eleitoral.","STF, MS 26.602; ADI 5081.","estende aos majoritários",jur=True)
X(6,43,"excecao_omitida",4,"No julgamento da ADI 5081, o STF entendeu que a perda do mandato por infidelidade partidária não se aplica aos cargos majoritários, pois o sistema majoritário privilegia a escolha do candidato.","No julgamento da ADI 5081, o STF entendeu que a perda do mandato por infidelidade partidária se aplica igualmente aos cargos proporcionais e majoritários, inclusive Senadores e Chefes do Executivo.","STF, ADI 5081 (2015).","inverte alcance",jur=True)
X(6,43,"excecao_omitida",4,"Na ADI 4650, o STF declarou inconstitucional o financiamento de campanhas eleitorais por pessoas jurídicas, subsistindo o financiamento por pessoas físicas e por recursos públicos.","Na ADI 4650, o STF declarou constitucional o financiamento de campanhas eleitorais por pessoas jurídicas, mas proibiu doações de pessoas físicas.","STF, ADI 4650 (2015).","inverte resultado",jur=True)
X(6,43,"excecao_omitida",3,"O Fundo Especial de Financiamento de Campanha (FEFC) é constituído por recursos públicos e destina-se ao financiamento das campanhas eleitorais, e sua divisão entre os partidos obedece a critérios definidos em lei, relacionados à representação na Câmara dos Deputados e no Senado.","O Fundo Especial de Financiamento de Campanha (FEFC) é constituído por doações de pessoas jurídicas e distribui-se de modo igualitário entre todos os partidos, independentemente de representação no Congresso.","Lei 9.504/1997, arts. 16-C e 16-D.","altera origem e critério",lei=True)
X(6,43,"troca_numero",4,"Pela EC 97/2017, em 2026 terão acesso aos recursos do fundo partidário e ao tempo de propaganda gratuita no rádio e na televisão os partidos que obtiverem, nas eleições para a Câmara dos Deputados, ao menos 2,5% dos votos válidos, distribuídos em pelo menos um terço das unidades da Federação, com mínimo de 1,5% em cada uma, ou que elegerem ao menos treze deputados distribuídos em pelo menos um terço das unidades da Federação.","Pela EC 97/2017, em 2026 terão acesso aos recursos do fundo partidário e ao tempo de propaganda gratuita no rádio e na televisão os partidos que obtiverem, nas eleições para a Câmara dos Deputados, ao menos 1,5% dos votos válidos, distribuídos em pelo menos um terço das unidades da Federação, com mínimo de 1% em cada uma, ou que elegerem ao menos nove deputados.","CF, art. 17, § 3º, e EC 97/2017, art. 3º.","usa percentuais de 2018",lei=True)
X(6,43,"troca_numero",3,"As federações partidárias, previstas na Lei 14.208/2021, atuam como uma só agremiação em âmbito nacional, devem durar no mínimo quatro anos e ser constituídas até a data da convenção partidária.","As federações partidárias, previstas na Lei 14.208/2021, têm caráter apenas estadual, podem ser desfeitas a qualquer tempo e devem ser constituídas até o fim das eleições.","Lei 14.208/2021.","altera abrangência, duração e prazo",lei=True)
X(6,43,"excecao_omitida",3,"Os partidos políticos são proibidos de utilizar organização paramilitar e de receber recursos financeiros de entidade ou governo estrangeiros ou de subordinação a eles, nos termos da Constituição.","Os partidos políticos podem receber recursos financeiros de governos estrangeiros, desde que declarados ao Tribunal Superior Eleitoral.","CF, art. 17, caput e II.","permite recurso estrangeiro",lei=True)
